import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup } from '@angular/forms';
import { Router } from '@angular/router';
import { ToastrService } from 'ngx-toastr';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent implements OnInit {

  public inputType: boolean = false;


  public formGroup!: FormGroup

  constructor(private _formBuilder: FormBuilder, private _router: Router, private _toastr: ToastrService) {

  }


  ngOnInit(): void {
    this._buildForm()
  }

  public onClickPasswordType() {
    this.inputType = !this.inputType
  }


  private _buildForm(): void {
    this.formGroup = this._formBuilder.group({
      email: '',
      password: ''
    })
  }


  public onSubmit(): void {
    localStorage.setItem('login', JSON.stringify(this.formGroup.value))
    const raw = localStorage.getItem('login');
    if (!raw) {
      return
    }
    const loginCredential = JSON.parse(raw)
    if (loginCredential.email === 'chanja@gmail.com' && loginCredential.password === 'chanja@123') {
      this._router.navigate(['home']);
      this._toastr.success('Logged in succesfully')
    }
    else {
      this._toastr.error('User name or password not correct')

    }
  }

}
<div class="login mt-5">
  <div class="card">
    <div class="card-header">
      <div class="container text-center">
        <h6>Sign In</h6>
      </div>
    </div>
    <div class="card-body">
      <form [formGroup]="formGroup" (ngSubmit)="onSubmit()">
        <div class="container">
          <div class="row">
            <div class="col">
              <label for="email" class="form-label">Email</label>
              <input
                type="email"
                class="form-control"
                name="email"
                id="email"
                formControlName="email"
              />
            </div>
          </div>
          <div class="row mt-2">
            <div class="col">
              <label for="password" class="form-label">Password</label>
              <div class="position-relative">
                <input
                  [type]="inputType ? 'text' : 'password'"
                  class="form-control"
                  name="password"
                  id="password"
                  formControlName="password"
                />
                <button
                  type="button"
                  class="btn position-absolute"
                  (click)="onClickPasswordType()"
                >
                  <img
                    class="pwd-icon"
                    [src]="
                      inputType
                        ? '../../../assets/icons/eye open.png'
                        : '../../../assets/icons/eye close.png'
                    "
                    alt=""
                  />
                </button>
              </div>
            </div>
          </div>
          <div class="row mt-5 justify-content-center">
            <button class="login-btn" type="submit">Log In</button>
          </div>
        </div>
      </form>
    </div>
  </div>
</div>
